pre_install:
if (!(is_admin)) { throw "$app requires admin rights to $cmd" }

if (@($fname).Count -ne 2) {
    throw "MuMuPlayer needs exactly two installers: NX-main and MUMU15."
}

$transactionId = "00000000-0000-0000-0000-000000000000"
$versionParts = $version -split "\."
if ($versionParts.Count -lt 3) {
    throw "Cannot derive MuMuPlayer product version from NXMAIN version $version."
}
$productVersion = "6.$($versionParts[1]).$($versionParts[2]).0"
$scoopRoot = Split-Path (Split-Path (Split-Path $dir -Parent) -Parent) -Parent
$stagingDir = Join-Path $scoopRoot "cache\mumuplayer-installers-$([guid]::NewGuid().ToString())"
New-Item -ItemType Directory -Path $stagingDir -Force | Out-Null

try {
    $installerPaths = @()
    for ($i = 0; $i -lt 2; $i++) {
        $sourceInstaller = Join-Path $dir $fname[$i]
        $downloadUrl = "https://a11.gdl.easebar.com/$($fname[$i])"
        $cachedInstaller = cache_path $app $version $downloadUrl

        if (Test-Path -LiteralPath $cachedInstaller) {
            $installerPath = $cachedInstaller
            Remove-Item -LiteralPath $sourceInstaller -Force
        } else {
            $installerPath = Join-Path $stagingDir $fname[$i]
            Copy-Item -LiteralPath $sourceInstaller -Destination $installerPath -Force
            Remove-Item -LiteralPath $sourceInstaller -Force
        }
        $installerPaths += $installerPath
    }

    $remainingFiles = @(Get-ChildItem -LiteralPath $dir -Force)
    if ($remainingFiles.Count -gt 0) {
        throw "MuMuPlayer target directory must be empty before setup. Unexpected item: $($remainingFiles[0].FullName)"
    }

    $commonArguments = @(
        "/from_orchestrator=1",
        "/txn_id=$transactionId",
        "/silent=1",
        "/product_version=$productVersion",
        "/auto_start=false",
        "/fchannel=gw-win-download",
        "/auto_run=false",
        "/D=$dir"
    )

    $prepareArguments = @("/from_orchestrator=1", "/action=install_prepare") + $commonArguments[1..($commonArguments.Count - 1)]
    $prepareNx = Start-Process -FilePath $installerPaths[0] -ArgumentList $prepareArguments -Wait -PassThru
    if ($prepareNx.ExitCode -ne 0) {
        throw "MuMuPlayer NX-main install_prepare failed with exit code $($prepareNx.ExitCode)."
    }

    Start-Sleep -Seconds 12

    $prepareMumu15 = Start-Process -FilePath $installerPaths[1] -ArgumentList $prepareArguments -Wait -PassThru
    if ($prepareMumu15.ExitCode -ne 0) {
        throw "MuMuPlayer MUMU15 install_prepare failed with exit code $($prepareMumu15.ExitCode)."
    }

    Start-Sleep -Seconds 12

    $commitArguments = @("/from_orchestrator=1", "/action=commit") + $commonArguments[1..($commonArguments.Count - 1)]
    $commitMumu15 = Start-Process -FilePath $installerPaths[1] -ArgumentList $commitArguments -Wait -PassThru
    if ($commitMumu15.ExitCode -ne 0) {
        throw "MuMuPlayer MUMU15 commit failed with exit code $($commitMumu15.ExitCode)."
    }

    Start-Sleep -Seconds 12

    $commitNx = Start-Process -FilePath $installerPaths[0] -ArgumentList $commitArguments -Wait -PassThru
    if ($commitNx.ExitCode -ne 0) {
        throw "MuMuPlayer NX-main commit failed with exit code $($commitNx.ExitCode)."
    }

    $mainExe = Join-Path $dir "nx_main\MuMuNxMain.exe"
    if (-not (Test-Path $mainExe)) {
        throw "MuMuPlayer setup returned successfully but did not create the expected executable: $mainExe"
    }
}
finally {
    Remove-Item -LiteralPath $stagingDir -Recurse -Force -ErrorAction SilentlyContinue
}
